package com.bank.prefix;

import java.util.List;
import java.util.logging.Logger;

// Extracts the common branch prefix of account numbers for National Bank of India.
public class PrefixExtractor {
    private static final Logger log = Logger.getLogger(PrefixExtractor.class.getName());

    // Longest common prefix by vertical scan. O(total chars examined).
    public String longestCommonPrefix(List<String> numbers) {
        if (numbers == null || numbers.isEmpty()) {
            return "";                              // no strings → empty prefix
        }
        String first = numbers.get(0);              // reference string
        for (int i = 0; i < first.length(); i++) {
            char c = first.charAt(i);               // candidate prefix char
            for (String s : numbers) {
                if (i >= s.length() || s.charAt(i) != c) {
                    String prefix = first.substring(0, i);
                    log.info(() -> "Common prefix = '" + prefix + "'");
                    return prefix;                  // first mismatch or end
                }
            }
        }
        log.info(() -> "Common prefix = '" + first + "' (whole reference)");
        return first;                               // reference is the full prefix
    }
}
