package com.bank.prefix;

import java.util.List;
import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

// Runnable demo: common prefix of account-number batches.
public class PrefixExtractorDemo {
    private static final Logger log = Logger.getLogger(PrefixExtractorDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        PrefixExtractor extractor = new PrefixExtractor();

        List<String> batch = List.of("SAV2001", "SAV2002", "SAV2015");
        log.info(() -> "Result = " + extractor.longestCommonPrefix(batch));

        List<String> mixed = List.of("SAV2001", "CUR3001");
        log.info(() -> "Result = " + extractor.longestCommonPrefix(mixed));
    }
}
